<template>
  <div class="page-shell"><a-card title="权限目录" :loading="loading" :bordered="false"><a-list :data-source="catalog" item-layout="vertical"><template #renderItem="{ item }"><a-list-item><a-list-item-meta :title="item.module" /><a-space wrap><a-tag v-for="permission in item.permissions" :key="permission.code">{{ permission.name }} · {{ permission.code }}</a-tag></a-space></a-list-item></template></a-list></a-card></div>
</template>
<script setup>
import { onMounted, onUnmounted, ref } from 'vue'; import { message } from 'ant-design-vue'; import { getPermissionCatalog } from '@/api/admin'; import { registerModelContextTools } from '@/utils/webmcp'
const catalog = ref([]); const loading = ref(false); const loadCatalog = async () => { loading.value = true; try { catalog.value = (await getPermissionCatalog()).catalog || [] } catch { message.error('权限目录加载失败') } finally { loading.value = false } }; let unregisterWebMcpTools = () => {}; const registerWebMcpTools = () => { unregisterWebMcpTools = registerModelContextTools([{ name: 'read_openhrm_permission_catalog', title: '读取权限目录', description: '读取系统可分配的权限模块和权限编码，不修改角色或用户授权。', inputSchema: { type: 'object', properties: {}, additionalProperties: false }, annotations: { readOnlyHint: true }, async execute() { await loadCatalog(); return { catalog: catalog.value.map(group => ({ module: group.module, permissions: (group.permissions || []).map(({ code, name }) => ({ code, name })) })) } } }]) }; onMounted(() => { registerWebMcpTools(); loadCatalog() }); onUnmounted(() => unregisterWebMcpTools())
</script>
<style scoped>.page-shell { min-height: calc(100vh - 48px); padding: 24px; background: #f5f7fa; }</style>
